import{_ as a,o,c as t,a2 as s}from"./chunks/framework.1C62pOns.js";const r="/pro-agent-hub-installer/capturas/pt/agentes-detalhe.png",n="/pro-agent-hub-installer/capturas/pt/agentes-codigo.png",i="/pro-agent-hub-installer/capturas/pt/times-fluxo.png",c="/pro-agent-hub-installer/capturas/pt/chat.png",f=JSON.parse('{"title":"Agentes, times e chat","description":"","frontmatter":{},"headers":[],"relativePath":"pt/interface/agentes.md","filePath":"pt/interface/agentes.md","lastUpdated":1787856241000}'),d={name:"pt/interface/agentes.md"};function m(l,e,p,u,g,h){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="agentes-times-e-chat" tabindex="-1">Agentes, times e chat <a class="header-anchor" href="#agentes-times-e-chat" aria-label="Permalink to &quot;Agentes, times e chat&quot;">​</a></h1><h2 id="agentes" tabindex="-1">Agentes <a class="header-anchor" href="#agentes" aria-label="Permalink to &quot;Agentes&quot;">​</a></h2><p><img src="'+r+'" alt="agentes-detalhe"></p><p>Um <strong>agente</strong> é um modelo com instruções, ferramentas e, opcionalmente, conhecimento. É a unidade que conversa e executa.</p><h3 id="aba-instrucoes" tabindex="-1">Aba Instruções <a class="header-anchor" href="#aba-instrucoes" aria-label="Permalink to &quot;Aba Instruções&quot;">​</a></h3><p>É onde o agente ganha personalidade e limites. Três campos, com papéis diferentes:</p><ul><li><strong>Descrição do agente</strong> — quem ele é. Vai no início do contexto.</li><li><strong>Instrução</strong> — como ele deve agir. É o campo que mais muda o resultado.</li><li><strong>Saída esperada</strong> — o formato da resposta, quando você precisa de algo estruturado.</li></ul><p><strong>Histórico</strong>: ligar <em>adicionar histórico ao contexto</em> faz o agente lembrar da conversa. O número de execuções anteriores é o que ele carrega — mais histórico custa mais tokens em toda pergunta.</p><h3 id="aba-ferramentas" tabindex="-1">Aba Ferramentas <a class="header-anchor" href="#aba-ferramentas" aria-label="Permalink to &quot;Aba Ferramentas&quot;">​</a></h3><p>Ferramentas prontas (busca web, Wikipédia, gráficos), serviços MCP vinculados e os conhecimentos que ele pode consultar.</p><p>Um agente pode ter <strong>vários conhecimentos</strong>. A busca acontece em todos, e os trechos mais próximos entram no contexto.</p><h3 id="aba-codigo" tabindex="-1">Aba Código <a class="header-anchor" href="#aba-codigo" aria-label="Permalink to &quot;Aba Código&quot;">​</a></h3><p><img src="'+n+'" alt="agentes-codigo"></p><p>Cada função de topo que você escrever aqui vira uma ferramenta do agente — o modelo decide quando chamá-la, lendo o nome e a docstring. Escreva as duas pensando em quem vai ler: o leitor é o modelo.</p><div class="danger custom-block"><p class="custom-block-title">Aqui não existe nenhuma função da plataforma</p><p>Este é o único lugar de código da plataforma que roda em <strong>escopo vazio</strong>. <code>db_query</code>, <code>send_email</code> e as demais operações <strong>não existem</strong> aqui — usá-las dá <code>NameError</code>. Use <code>import</code> para o que precisar. Ver <a href="/pro-agent-hub-installer/pt/funcoes/agente_tool">Agente — código de ferramenta</a>.</p></div><h2 id="times" tabindex="-1">Times <a class="header-anchor" href="#times" aria-label="Permalink to &quot;Times&quot;">​</a></h2><p><img src="'+i+'" alt="times-fluxo"></p><p>Um <strong>time</strong> organiza agentes numa hierarquia: um coordenador que recebe a pergunta e delega a especialistas. Faz sentido quando um único agente ficaria com instruções longas demais, ou quando cada parte precisa de um modelo diferente.</p><p>A aba <strong>Fluxo</strong> é um quadro onde você monta a hierarquia arrastando agentes e subtimes. Cada nó carrega o papel e as instruções específicas daquele integrante naquele time — o mesmo agente pode participar de times diferentes com papéis diferentes.</p><h2 id="chat" tabindex="-1">Chat <a class="header-anchor" href="#chat" aria-label="Permalink to &quot;Chat&quot;">​</a></h2><p><img src="'+c+'" alt="chat"></p><p>A tela de conversa. Escolha um agente ou um time e converse. Aceita anexar arquivos e imagens quando o modelo suporta.</p><p>É também o lugar de testar antes de automatizar: se o agente não responde bem no chat, ele não vai responder bem dentro de um workflow.</p>',23)])])}const q=a(d,[["render",m]]);export{f as __pageData,q as default};
